async function render(){
 const ticket=++renderId,raw=location.hash.slice(1)||'home',[baseQuery,param]=raw.split('/'),[base]=baseQuery.split('?');
 $('.sidebar').classList.remove('open');document.querySelectorAll('.nav-link[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===base));
 $('#main').setAttribute('aria-busy','true');let html='';
 try{
  if(['home','discover','charts','artists','producers','search'].includes(base)){
   let query='';const genre=base==='discover'?decodeURIComponent(param||'전체'):'전체',searchValue=base==='search'?decodeURIComponent(param||''):'';
   if(base==='charts')query='?chart='+({rising:'rising',newcomers:'newcomers',releases:'releases'}[param]||'top');
   if(base==='discover'&&genre!=='전체')query='?genre='+encodeURIComponent(genre);
   if(base==='search')query='?q='+encodeURIComponent(searchValue);
   const data=await api('/api/catalog'+query);routeTracks=remember(data.tracks);
   if(base==='home')html=heading('오늘, 어떤 음악을 만나볼까요?','취향을 넓히는 새로운 음악과 창작자를 발견하세요.')+`<section class="hero aifect-hero"><div class="hero-copy"><span class="eyebrow">THE NEXT SOUND</span><h2>상상이 음악이 되는 곳.<br>당신의 다음 플레이리스트.</h2><p>AI가 열어준 가능성, 창작자가 담아낸 감성.<br>마음에 닿는 새로운 사운드를 만나보세요.</p><div class="hero-actions"><a class="primary-button" href="#discover">음악 둘러보기 ${icon('play')}</a><a href="#upload" class="text-link">내 음악 공개하기 ${icon('arrow')}</a></div><span class="hero-bottom">DISCOVER · LISTEN · CONNECT</span></div><div class="live-hero-art" aria-hidden="true"><div>A<span>IFECT</span></div></div></section>`+section('새롭게 도착한 음악','#charts/releases')+grid(data.tracks.slice(0,5))+section('새로운 목소리를 만나보세요','#artists')+identityCards(data.artists.slice(0,4),'artist')+`<div class="preview-notice"><div><span class="tiny-eyebrow">YOUR NEXT FAVORITE</span><p>60초의 첫 만남, 회원은 전체곡을 무료로.</p></div><a class="primary-button" href="#${me?'discover':'account'}">${me?'음악 발견하기':'무료로 시작하기'} ${icon('arrow')}</a></div>`;
   else if(base==='discover')html=heading('음악 발견','장르를 넘나들며 새로운 취향을 찾아보세요.')+`<div class="genre-chips">${genres.map(g=>`<a class="genre-chip ${g===genre?'active':''}" href="#discover/${encodeURIComponent(g)}">${g}</a>`).join('')}</div>`+grid(data.tracks);
   else if(base==='charts')html=heading('AIFECT 차트','실제 감상과 좋아요·댓글로 함께 만드는 차트입니다.')+`<div class="tabs">${[['','TOP 100'],['rising','급상승'],['newcomers','신인'],['releases','신곡']].map(([k,v])=>`<a class="tab ${(param||'')===k?'active':''}" href="#charts${k?'/'+k:''}">${v}</a>`).join('')}</div>`+list(data.tracks);
   else if(base==='artists'||base==='producers')html=heading(base==='artists'?'AI 아티스트':'제작자',base==='artists'?'새로운 목소리, 새로운 세계.':'당신이 좋아하는 음악을 만드는 사람들.')+identityCards(data[base],base==='artists'?'artist':'producer');
   else html=heading('음악 검색')+`<form id="search-form" class="aifect-search">${icon('search')}<input name="q" aria-label="곡, 아티스트, 제작자 검색" placeholder="곡, 아티스트, 제작자, 태그" value="${esc(searchValue)}" maxlength="100"><button class="primary-button">검색</button></form><p class="search-caption">${searchValue?`“${esc(searchValue)}” 검색 결과 ${data.tracks.length}곡`:'어떤 음악을 찾고 계신가요?'}</p>`+list(data.tracks);
  }else if(base==='song'){
   const {track:t}=await api('/api/tracks/'+param);remember([t]);const {comments}=await api(`/api/tracks/${param}/comments`);routeTracks=[t];
   html=heading('곡 이야기')+`<section class="song-detail">${cover(t)}<div><span class="eyebrow">${esc(t.genre)} · ${time(t.duration)}</span><h2>${esc(t.title)}</h2><div class="song-credits"><div><span>AI ARTIST</span><a href="#artist/${t.artist_id}">${esc(t.artist)}</a></div><div><span>PRODUCER</span><a href="#producer/${t.producer_id}">${esc(t.producer)}</a></div></div><p class="song-description">${esc(t.description||'음악을 듣고 감상을 나눠보세요.')}</p><div class="inline-actions"><button class="primary-button" data-play="${t.id}">${icon('play')} ${me?'전체곡 듣기':'60초 미리 듣기'}</button><button class="small-button" data-like="${t.id}">${icon('heart')} ${number(t.likes)}</button><button class="small-button" data-add="${t.id}">${icon('plus')} 저장</button></div><p class="song-metrics">${number(t.plays)}회 감상 · ${number(t.comments)}개 댓글</p></div></section><div class="song-columns"><section class="surface comments-panel"><div class="section-heading"><h2>함께 듣는 이야기</h2><select id="comment-sort" aria-label="댓글 정렬"><option value="latest">최신순</option><option value="popular">인기순</option><option value="timeline">타임라인순</option></select></div><form id="comment-form"><textarea name="body" maxlength="2000" required placeholder="${me?'이 곡의 어떤 순간이 좋았나요?':'로그인 후 감상을 남겨보세요.'}" aria-label="댓글"></textarea><div class="comment-compose-bottom"><label><input name="with_time" type="checkbox" checked> 현재 재생 시간 포함</label><button class="primary-button">댓글 등록</button></div><p class="form-error" role="alert"></p></form><div id="comments">${commentsHTML(comments,t)}</div></section><aside class="song-sidebar"><section class="surface"><h3>이 음악의 크레딧</h3><dl class="production-info"><dt>AI 도구</dt><dd>${esc(t.ai_tool)}</dd><dt>사람의 참여</dt><dd>${esc(t.participation||'—')}</dd><dt>장르</dt><dd>${esc(t.genre)}</dd><dt>태그</dt><dd>${esc(t.tags||'—')}</dd></dl></section></aside></div>`;
  }else if(base==='artist'||base==='producer'){
   const d=await api(`/api/${base==='artist'?'artists':'producers'}/${param}`);routeTracks=remember(d.tracks);
   html=heading(base==='artist'?'AI 아티스트':'제작자')+`<section class="profile-hero surface"><div class="artist-portrait cover cover-lime">${esc(d.profile.name.slice(0,2))}</div><div><span class="eyebrow">${base==='artist'?'AI ARTIST':'PRODUCER'}</span><h2>${esc(d.profile.name)}</h2><p>${esc(d.profile.bio||'새로운 음악으로 만나요.')}</p><div class="inline-actions"><span>${number(d.followers)} 팔로워 · ${d.tracks.length}곡</span><button class="primary-button" data-follow="${base}/${param}">${followed(base,param)?'팔로잉':'팔로우'}</button></div></div></section>`+section('공개한 음악')+list(d.tracks);
  }else if(['library','history','studio','upload','manage'].includes(base)&&!me){returnRoute=location.hash;html=gate();}
  else if(base==='library'){
   await refreshLibrary();const tab=param||'likes';routeTracks=library.likes;
   html=heading('내 보관함','좋아하는 음악과 창작자를 한곳에서.')+`<div class="tabs">${[['likes','좋아요'],['playlists','플레이리스트'],['artists','아티스트'],['producers','제작자']].map(([k,v])=>`<a class="tab ${tab===k?'active':''}" href="#library/${k}">${v}</a>`).join('')}</div>`;
   if(tab==='playlists')html+=`<div class="playlist-actions"><button class="primary-button" id="new-playlist">${icon('plus')} 플레이리스트 만들기</button></div>`+playlistsHTML(library.playlists);
   else if(tab==='artists'||tab==='producers')html+=identityCards(library.follows.filter(f=>f.kind===(tab==='artists'?'artist':'producer')).map(f=>({id:f.target_id,name:f.name})),tab==='artists'?'artist':'producer');
   else html+=list(library.likes);
  }else if(base==='history'){const d=await api('/api/history');routeTracks=remember(d.tracks);html=heading('최근 들은 음악','다시 듣고 싶은 순간을 찾아보세요.')+list(d.tracks);}
  else if(base==='playlist'){
   const d=await api('/api/playlists/'+param);routeTracks=remember(d.tracks);const owned=me?.id===d.playlist.user_id;
   html=heading(esc(d.playlist.name),`${d.tracks.length}곡 · ${d.playlist.is_public?'공개 플레이리스트':'나만 보는 플레이리스트'}`)+`<div class="inline-actions playlist-actions"><button class="primary-button" data-play-all>전체 재생 ${icon('play')}</button>${owned?`<button class="small-button" data-edit-playlist="${param}">이름 · 공개 설정</button><button class="small-button" data-delete-playlist="${param}">삭제</button>`:''}${d.playlist.is_public?`<button class="small-button" data-share>링크 복사</button>`:''}</div>`+list(d.tracks,owned?param:null);
  }else if(base==='account')html=accountHTML();
  else if(base==='upload')html=uploadHTML();
  else if(base==='studio'||base==='manage'){
   const d=await api('/api/studio');
   html=heading('창작자 스튜디오','음악을 공개하고 당신의 리스너를 만나보세요.')+`<div class="stats-grid"><div class="stat-card"><span>공개한 음악</span><strong>${d.tracks.filter(t=>t.status==='published').length}</strong></div><div class="stat-card"><span>업로드 · 변환 중</span><strong>${d.tracks.filter(t=>['queued','processing','uploading'].includes(t.status)).length}</strong></div><div class="stat-card"><span>AI 아티스트</span><strong>${d.artists.length}</strong></div></div><div class="section-heading"><h2>내 음원 관리</h2><a class="primary-button" href="#upload">음원 업로드 ${icon('plus')}</a></div><div class="surface">${d.tracks.length?d.tracks.map(t=>`<div class="studio-track"><div><strong>${esc(t.title)}</strong><p>${{uploading:'파일 전송 대기',queued:'변환 대기',processing:'AAC 128kbps로 변환 중',published:'공개됨',hidden:'비공개',failed:'변환 실패'}[t.status]}</p>${t.error?`<small class="form-error">${esc(t.error)}</small>`:''}</div><div class="inline-actions">${t.status==='published'?`<a class="small-button" href="#song/${t.id}">곡 보기</a><button class="small-button" data-hide-track="${t.id}">비공개로 전환</button>`:['failed','hidden'].includes(t.status)?`<button class="small-button" data-retry-track="${t.id}">${t.status==='hidden'?'다시 공개':'다시 변환'}</button>`:''}</div></div>`).join(''):'아직 업로드한 곡이 없습니다.'}</div>`+section('제작자 프로필')+`<form id="producer-form" class="surface upload-form">${formField('제작자 이름','name','text',d.producer?.name||me.name,'required maxlength="60"')}<label class="form-field">소개<textarea name="bio" maxlength="1000">${esc(d.producer?.bio||'')}</textarea></label><button class="primary-button">프로필 저장</button><p class="form-error" role="alert"></p></form>`;
  }else html=heading('페이지를 찾을 수 없어요')+empty('잠시 길을 잃었네요','홈에서 새로운 음악을 발견해보세요.','#home','홈으로 이동');
  if(ticket!==renderId)return;
  $('#main').innerHTML=html;$('#main').removeAttribute('aria-busy');icons();bindForms(base,param);window.scrollTo({top:0,behavior:'instant'});
 }catch(e){if(ticket!==renderId)return;$('#main').innerHTML=heading('다시 연결해주세요')+`<div class="surface empty-design"><p>${esc(e.message)}</p><button class="primary-button" id="reload-page">다시 시도</button></div>`;$('#reload-page').onclick=render;$('#main').removeAttribute('aria-busy');}
}
function accountHTML(){
 if(me)return heading('내 계정')+`<div class="surface login-card"><h2>${esc(me.name)}님, 반가워요.</h2><p>${me.email.endsWith('.invalid')?'소셜 로그인 계정':esc(me.email)}</p><p>무료 회원 · 전체곡 AAC 128kbps 감상</p><div class="inline-actions"><a class="primary-button" href="#library">내 보관함</a><button class="small-button" id="logout">로그아웃</button></div></div>`;
 const error=location.hash.includes('?error=')?decodeURIComponent(location.hash.split('?error=')[1]):'';
 return `<section class="login-layout"><div class="login-story"><span class="eyebrow">AIFECT · AI + EFFECT</span><h1>새로운 취향의 시작.<br><em>마음껏, 무료로.</em></h1><p>회원이 되면 모든 곡을 끝까지 들을 수 있어요.<br>좋아하는 음악을 모으고 창작자와 이야기를 나눠보세요.</p><div class="login-perks"><span>${icon('play')} 전체곡 무료 스트리밍</span><span>${icon('heart')} 좋아요와 나만의 플레이리스트</span><span>${icon('users')} 아티스트 · 제작자 팔로우</span></div></div><div class="surface login-card"><span class="eyebrow">WELCOME TO AIFECT</span><h2 id="auth-title">이메일로 로그인</h2><p>새로운 음악이 기다리고 있어요.</p>${error?`<p class="form-error">${esc(error)}</p>`:''}<form id="auth-form" data-mode="login"><div id="signup-name" hidden>${formField('닉네임','name','text','','maxlength="40" autocomplete="nickname"')}</div>${formField('이메일','email','email','','required autocomplete="email"')}${formField('비밀번호','password','password','','required minlength="12" maxlength="128" autocomplete="current-password" placeholder="12자 이상"')}<button class="primary-button full-width" id="auth-submit">로그인</button><p class="form-error" role="alert"></p></form><button class="text-link auth-switch" id="auth-switch">처음 오셨나요? 무료 회원가입</button><div class="login-divider">소셜 계정으로 계속하기</div>${[['google','Google'],['kakao','카카오'],['apple','Apple']].map(([p,n])=>authConfig.providers?.includes(p)?`<a class="social-login ${p}" href="/api/auth/${p}" data-oauth>${n}로 계속하기</a>`:`<button class="social-login ${p}" disabled>${n} · 연결 준비 중</button>`).join('')}<p class="login-note">회원은 모든 곡을 무료로 감상할 수 있습니다.</p></div></section>`;
}
function uploadHTML(){return heading('음원 업로드','당신의 상상이 누군가의 새로운 취향이 됩니다.')+`<div class="upload-layout"><form id="upload-form" class="surface upload-form"><h2>음악과 커버</h2><div class="file-zones"><label class="file-zone">${icon('upload')}<strong>원본 음원 선택</strong><span>WAV · FLAC · MP3 / 최대 80MB</span><input name="audio" type="file" accept=".wav,.flac,.mp3" required></label><label class="file-zone">${icon('plus')}<strong>커버 이미지 선택</strong><span>JPG · PNG · WebP / 최대 5MB</span><input name="cover" type="file" accept="image/jpeg,image/png,image/webp"></label></div><h2>곡 정보</h2>${formField('곡 제목','title','text','','required maxlength="120"')}<div class="form-grid">${formField('AI 아티스트 이름','artist','text','','required maxlength="60"')}${formField('제작자 이름','producer','text',me.name,'required maxlength="60"')}</div><label class="form-field">장르<select name="genre">${genres.slice(1).map(g=>`<option>${g}</option>`).join('')}</select></label>${formField('태그 (쉼표로 구분)','tags','text','','maxlength="300"')}<label class="form-field">곡 소개<textarea name="description" maxlength="4000" placeholder="이 음악에 담은 이야기를 들려주세요."></textarea></label>${formField('사용한 AI 도구','ai_tool','text','','required maxlength="100" placeholder="예: Suno, Udio"')}<div class="participation">사람이 참여한 부분 ${['작사','작곡','편곡','보컬','믹싱'].map(v=>`<label><input type="checkbox" name="participation" value="${v}">${v}</label>`).join('')}</div><label class="checkbox-line rights-check"><input name="is_ai" type="checkbox" required> AI를 활용해 제작한 음악입니다.</label><label class="checkbox-line rights-check"><input name="rights" type="checkbox" required> 이 음원과 커버를 업로드하고 스트리밍할 권리를 보유하고 있습니다. 무단 복제, 타인의 음성 복제, 권리 없는 재업로드가 아닙니다.</label><button class="primary-button" id="upload-submit">음원 업로드 ${icon('upload')}</button><div class="upload-progress" hidden><progress max="100" value="0"></progress><p role="status"></p></div><p class="form-error" role="alert"></p></form><aside class="surface upload-guide"><span class="eyebrow">MADE BY YOU</span><h2>들려주세요.<br>당신의 새로운 소리.</h2><p>5초부터 20분까지 업로드할 수 있어요. 원본은 비공개로 보관하고 감상용 음원과 60초 미리 듣기를 자동으로 만듭니다.</p><p>변환이 완료되면 음악이 공개됩니다. 진행 상황은 스튜디오에서 확인할 수 있어요.</p></aside></div>`;}
function playlistsHTML(items){return `<div class="playlist-grid">${items.map(p=>`<a class="playlist-card surface" href="#playlist/${p.id}"><div class="playlist-art cover-lime">${icon('list')}</div><h2>${esc(p.name)}</h2><p>${p.tracks}곡 · ${p.is_public?'공개':'비공개'}</p></a>`).join('')}</div>`;}
function commentsHTML(comments,t){
 const row=c=>`<article class="live-comment ${c.parent_id?'is-reply':''}"><div class="comment-avatar">${esc(c.name.slice(0,1))}</div><div><div><strong>${esc(c.name)}</strong>${c.creator?'<span class="creator-badge">PRODUCER</span>':''}<span class="comment-age">${new Date(c.created*1000).toLocaleDateString('ko-KR')}${c.edited?' · 수정됨':''}</span></div><p>${c.timestamp!==null?`<button class="timestamp" data-seek="${c.timestamp}" data-track="${t.id}">${time(c.timestamp)}</button>`:''}${esc(c.body)}</p><div class="inline-actions"><button class="text-link ${c.liked?'is-active':''}" data-comment-like="${c.id}" data-liked="${!!c.liked}">${icon('heart')} ${c.likes}</button>${!c.parent_id?`<button class="text-link" data-reply="${c.id}" data-track="${t.id}">답글</button>`:''}${me?.id===c.user_id?`<button class="text-link" data-edit-comment="${c.id}" data-body="${esc(c.body)}">수정</button><button class="text-link" data-delete-comment="${c.id}">삭제</button>`:''}</div></div></article>`;
 return comments.length?comments.filter(c=>!c.parent_id).map(c=>row(c)+comments.filter(r=>r.parent_id===c.id).map(row).join('')).join(''):'<p class="quiet">첫 감상을 남겨보세요.</p>';
}
